const QUICK_PREFIX='bible-study-quick-v1:';
function readQuick(key){try{let a=JSON.parse(localStorage.getItem(QUICK_PREFIX+key)||'[]');return Array.isArray(a)?a.filter(x=>typeof x==='string').slice(0,50):[]}catch{return []}}
function writeQuick(key,list){try{localStorage.setItem(QUICK_PREFIX+key,JSON.stringify(list))}catch{}}
function rememberPerson(name){let r=readQuick('recent').filter(x=>x!==name);r.unshift(name);writeQuick('recent',r.slice(0,5))}
function toggleFavorite(name){let fav=readQuick('favorites'),exists=fav.includes(name);writeQuick('favorites',exists?fav.filter(x=>x!==name):[name,...fav]);return !exists}
function renderQuick(){const box=$('#quick-links');if(!box)return;const valid=new Set(allPeople().map(p=>p.name)),fav=readQuick('favorites').filter(x=>valid.has(x)),recent=readQuick('recent').filter(x=>valid.has(x)&&!fav.includes(x));const chips=items=>items.map(x=>`<a href="${idHash(x)}">${esc(x)}</a>`).join('');box.innerHTML=(fav.length?`<div class="quick-row"><span>즐겨찾기 <small>이 기기</small></span><div class="quick-items">${chips(fav)}</div></div>`:'')+(recent.length?`<div class="quick-row"><span>최근 본 인물 <small>이 기기</small></span><div class="quick-items">${chips(recent)}</div><button class="link" id="clear-recent">지우기</button></div>`:'');$('#clear-recent')?.addEventListener('click',()=>{writeQuick('recent',[]);renderQuick()})}
function personView(name){const person=allPeople().find(p=>p.name===name)||virtualPerson(name);if(!person){$('#app').innerHTML='<div class="notice">인물을 찾지 못했습니다. <a href="#/people">목록으로 돌아가기</a></div>';return}currentPerson=name;if(!person.kind)rememberPerson(name);const own=notes.filter(n=>n.person===name||(person.kind==='book'&&n.book===person.display)||(person.kind==='verse'&&n.verse===person.display)||(person.kind==='topic'&&(n.topic||'').split(',').map(x=>x.trim()).includes(person.display))),display=personNotesFilter==='all'?own:own.filter(n=>n.author===personNotesFilter),term=person.search_term||searches[name]||name.replace(/ \(.*\)$/,'');const backLink=`<a class="back bottom-back" href="${person.kind?'#/'+({book:'books',topic:'topics',verse:'verses',family:'family'}[person.kind]):'#/people'}">← ${person.kind?({book:'성경 책',topic:'주제',verse:'성구',family:'가족 숭배'}[person.kind]):'인물 목록'}</a>`;$('#app').innerHTML=`<div class="person-top"><div>${!person.kind?`<div class="eyebrow">${esc(person.era)}</div>`:''}<h1>${esc(person.display||name)}</h1>${peopleHints[name]?`<p class="person-hint">${esc(peopleHints[name])}</p>`:''}</div><div class="person-actions">${person.kind==='topic'?`<a class="secondary family-topic-action" href="${idHash('@family:'+person.display)}?topic=${encodeURIComponent(person.display)}">가족 숭배에 기록</a>`:''}${!person.kind?`<button class="favorite-button" id="favorite-person" aria-pressed="${readQuick('favorites').includes(name)}">${readQuick('favorites').includes(name)?'★ 즐겨찾기':'☆ 즐겨찾기'}</button>`:''}<button type="button" class="action-icon" id="new-note" aria-label="새 기록 추가" title="새 기록 추가">${UI_PLUS}</button></div></div><a class="resource" href="https://www.jw.org/ko/%EA%B2%80%EC%83%89/?q=${encodeURIComponent(term)}" target="_blank" rel="noopener noreferrer"><span><strong>JW.ORG 자료</strong></span><span>↗</span></a>${person.kind==='topic'?relatedTopics(person.display):''}${!person.kind?connectionSection('resource',name,'저장한 자료')+connectionSection('person',name,'관련 인물'):person.kind==='family'?connectionSection('question',name,'다음 질문'):person.kind==='topic'?topicQuestions(person.display):''}${representatives[name]?`<div class="verse-tip"><strong>성구</strong><a href="${esc(verseUrl(representatives[name]))}" target="_blank" rel="noopener noreferrer">${esc(representatives[name])} ↗</a></div>`:''}<div class="section-row"><div><h2>기록 <span class="count">${own.length}</span></h2></div><div class="filters" aria-label="작성자 필터">${[['all','전체'],['mine','민수'],['bora','보라']].map(([v,l])=>`<button data-filter="${v}" aria-pressed="${personNotesFilter===v}" class="${personNotesFilter===v?'active':''}">${l}</button>`).join('')}</div></div><div class="notes-list">${display.length?display.map(noteCard).join(''):'<div class="empty">기록 없음</div>'}</div>${backLink}`;$('#favorite-person')?.addEventListener('click',e=>{const enabled=toggleFavorite(name);e.currentTarget.setAttribute('aria-pressed',String(enabled));e.currentTarget.textContent=enabled?'★ 즐겨찾기':'☆ 즐겨찾기'});$('#new-note').onclick=()=>openEditor();document.querySelector('.empty-new')?.addEventListener('click',()=>openEditor());document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{personNotesFilter=b.dataset.filter;personView(name)});bindNotes();loadImages(display);bindConnections(name)}
function sideNotes(list){if(!list.length)return ''; return list.slice(0,3).map(n=>`<a href="${idHash(n.person)}?note=${encodeURIComponent(n.id)}" class="side-note">${esc(n.title)}</a>`).join('')+(list.length>3?`<a class="side-note side-more" href="${idHash(list[0].person)}">${list.length-3}개 더 보기</a>`:'')}
function renderPeopleResults(){const q=query.trim().toLocaleLowerCase(),all=allPeople(), matching=all.filter(p=>(eraFilter==='all'||p.era===eraFilter)&&(!q||(p.name+' '+p.era+' '+notes.filter(n=>n.person===p.name).map(n=>[n.title,n.body,n.verse,n.topic,n.book].join(' ')).join(' ')).toLocaleLowerCase().includes(q)));const hits=q?notes.filter(n=>{const p=all.find(p=>p.name===n.person);return (eraFilter==='all'||p?.era===eraFilter)&&[n.person,n.title,n.body,n.verse,n.topic,n.book,n.author==='mine'?'민수':'보라'].join(' ').toLocaleLowerCase().includes(q)}):[];let hitHtml=hits.length?`<section class="search-hits"><h3>관련 연구 기록 <span class="count">${hits.length}</span></h3>${hits.map(n=>`<a class="explore-note" href="${idHash(n.person)}?note=${encodeURIComponent(n.id)}"><span><b>${esc(n.title)}</b><small>${esc(virtualPerson(n.person)?.display||n.person)} · ${n.author==='mine'?'민수':'보라'}${n.verse?' · '+esc(n.verse):''}</small><small>${esc(n.body.slice(0,90))}${n.body.length>90?'…':''}</small></span><span>→</span></a>`).join('')}</section>`:'';let section=eraNames.map(era=>{let list=matching.filter(p=>p.era===era);if(!list.length)return '';let open=q||eraFilter!=='all'||eraOpen.has(era);return `<details class="era-group" data-era="${esc(era)}" ${open?'open':''}><summary><span>${esc(era)}</span><small>${list.length}항목</small></summary>${list.map(p=>{const ns=notes.filter(n=>n.person===p.name);return `${phaseStarts[p.name]?`<div class="phase-label"><span>${esc(phaseStarts[p.name])}</span></div>`:''}<div class="person-row ${ns.length?'has-notes':'no-notes'}"><div class="side">${sideNotes(ns.filter(n=>n.author==='mine'))}</div><a class="person" href="${idHash(p.name)}">${esc(p.name)}</a><div class="side">${sideNotes(ns.filter(n=>n.author==='bora'))}</div></div>`}).join('')}</details>`}).join('');$('#results').innerHTML=(section||(!hitHtml?'<div class="empty">검색 결과가 없습니다. 다른 이름이나 단어로 찾아보세요.</div>':''))+hitHtml;$('#people-count').textContent=matching.length;document.querySelectorAll('[data-era]').forEach(d=>d.ontoggle=()=>{if(d.open)eraOpen.add(d.dataset.era);else eraOpen.delete(d.dataset.era)});}
function homeView(){
 const recentNotes=notes.slice().sort((a,b)=>String(b.updated_at||b.created_at).localeCompare(String(a.updated_at||a.created_at))).slice(0,3),latestFamily=notes.filter(n=>n.person.startsWith('@family:')).sort((a,b)=>String(b.updated_at||b.created_at).localeCompare(String(a.updated_at||a.created_at)))[0];
 const categories=[['people','인물','<circle cx="12" cy="8" r="3.2"/><path d="M5.5 20c.5-4.1 3-6 6.5-6s6 1.9 6.5 6"/>'],['topics','주제','<path d="M12 3v18M4 8l8-5 8 5v8l-8 5-8-5z"/><path d="M4 8l8 5 8-5"/>'],['family','가족 숭배','<path d="M3 11.5 12 4l9 7.5M6 10.5V20h12v-9.5M10 20v-5h4v5"/>'],['routine','영적 일과','<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 10h16m-11 5 2 2 4-4"/>']];
 $('#app').innerHTML=`<section class="study-home" aria-label="연구 분야"><div id="home-verses" class="home-verses"></div><nav class="home-categories" aria-label="연구 분야">${categories.map(([path,label,icon])=>`<a href="#/${path}" class="home-category"><span class="category-label"><svg class="category-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icon}</svg><span><span>${label}</span>${path==='family'&&latestFamily?`<small class="category-detail">${esc(latestFamily.title)} · ${esc(date(latestFamily.created_at))}</small>`:''}</span></span><span class="category-arrow" aria-hidden="true">→</span></a>`).join('')}</nav>${recentNotes.length?`<section class="home-recent"><h2>최근 연구</h2>${recentNotes.map(n=>`<a class="home-entry" href="${idHash(n.person)}?note=${encodeURIComponent(n.id)}"><span class="home-entry-text"><small>${esc(virtualPerson(n.person)?.display||n.person)} · ${n.author==='mine'?'민수':'보라'} · ${esc(date(n.created_at))}</small><strong>${esc(n.title)}</strong><span class="home-excerpt">${esc(n.body)}</span></span><span class="home-entry-photo" data-home-photo="${esc(n.id)}" hidden></span></a>`).join('')}</section>`:''}<div class="home-quick" id="quick-links"></div><div class="home-tools"><button class="home-settings" id="manage-open" aria-label="설정">설정</button></div></section>`;
 $('#manage-open').onclick=()=>$('#manage-dialog').showModal();renderHomeVerses();renderQuick();loadHomePhotos(recentNotes);
}
async function loadHomePhotos(ns){
 const ids=ns.map(n=>n.id).filter(id=>/^[0-9a-f-]{36}$/i.test(id));if(!ids.length)return;
 const list='note_id=in.('+ids.join(',')+')';
 try{const [a,b]=await Promise.all([fetch(BASE+'/rest/v1/study_images?select=note_id,data_url&'+list,{headers}),fetch(BASE+'/rest/v1/study_files?select=note_id,path&'+list,{headers})]);if(!a.ok||!b.ok)return;const legacy=await a.json(),files=await b.json();files.sort((x,y)=>x.path.split('/').pop().localeCompare(y.path.split('/').pop()));const images=[...files.filter(f=>/^[0-9a-f]{64}\/[0-9a-f-]{36}\.(jpg|png|webp|gif)$/.test(f.path)).map(f=>({id:f.note_id,src:fileUrl(f.path)})),...legacy.filter(f=>/^data:image\/(jpeg|png|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(f.data_url)).map(f=>({id:f.note_id,src:f.data_url}))];
 for(const item of images){const box=document.querySelector(`[data-home-photo="${item.id}"]`);if(!box||!box.hidden)continue;const img=document.createElement('img');img.alt='';img.loading='lazy';img.src=item.src;img.onerror=()=>{box.hidden=true};box.append(img);box.hidden=false}
 }catch{}
}
function peopleView(){$('#app').innerHTML=`<div class="workspace people-workspace"><div class="section-row people-header"><div><h1 class="people-title">인물 <span class="count" id="people-count" aria-live="polite"></span></h1></div><button type="button" class="action-icon" id="add-person" aria-label="인물 추가" title="인물 추가">${UI_PLUS}</button></div><div id="quick-links"></div><div class="toolbar"><button class="search-toggle" type="button" id="search-toggle" aria-label="${query?'검색 닫기':'검색 열기'}" aria-controls="search-panel" aria-expanded="${query?'true':'false'}"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"></circle><path d="m20 20-4-4"></path></svg></button><label class="search search-panel" id="search-panel" ${query?'':'hidden'}><input id="search" type="search" placeholder="인물, 성구, 주제, 기록 검색" aria-label="인물과 기록 검색" value="${esc(query)}"></label><select id="era-select" aria-label="시대 선택"><option value="all">모든 시대</option>${eraNames.map(e=>`<option value="${esc(e)}" ${eraFilter===e?'selected':''}>${esc(e)}</option>`).join('')}</select></div><details class="era-options"><summary>시대 보기</summary><div class="era-controls"><button class="link" id="open-eras">모두 펼치기</button><button class="link" id="close-eras">모두 접기</button></div></details><div class="column-head"><span>민수의 연구</span><span>인물</span><span>보라의 연구</span></div><div id="results"></div></div><a class="back bottom-back" href="#/home">← 처음</a>`;$('#search-toggle').onclick=()=>{const open=$('#search-panel').hidden;$('#search-panel').hidden=!open;$('#search-toggle').setAttribute('aria-expanded',String(open));$('#search-toggle').setAttribute('aria-label',open?'검색 닫기':'검색 열기');if(open)$('#search').focus();else if(query){query='';$('#search').value='';renderPeopleResults()}};let composing=false;$('#search').addEventListener('compositionstart',()=>{composing=true});$('#search').addEventListener('compositionend',e=>{composing=false;query=e.target.value;renderPeopleResults()});$('#search').addEventListener('input',e=>{query=e.target.value;if(!composing)renderPeopleResults()});$('#era-select').onchange=e=>{eraFilter=e.target.value;renderPeopleResults()};$('#open-eras').onclick=()=>{eraNames.forEach(e=>eraOpen.add(e));renderPeopleResults()};$('#close-eras').onclick=()=>{eraOpen.clear();renderPeopleResults()};$('#add-person').onclick=()=>{$('#person-form').reset();$('#person-message').textContent='';$('#person-dialog').showModal()};renderPeopleResults();renderQuick()}
let newContextKind='';
function exploreView(kind){const config={books:['','성경 책','성경 책을 직접 연구하거나 관련 인물 기록을 모아 봅니다.','book','book','성경 책','예: 창세기'],topics:['','주제','한 가지 주제를 직접 연구하거나 관련 기록을 모아 봅니다.','topic','topic','주제','예: 믿음'],verses:['','성구','성구를 직접 묵상하거나 관련 기록을 모아 봅니다.','verse','verse','성구','예: 시편 23:1']}[kind];let groupsMap=new Map();for(const n of notes){const values=kind==='topics'?(n.topic||'').split(','):[n[config[3]]||''];for(let v of values){v=v.trim();if(v){if(!groupsMap.has(v))groupsMap.set(v,[]);groupsMap.get(v).push(n)}}}const list=[...groupsMap].sort((a,b)=>a[0].localeCompare(b[0],'ko'));$('#app').innerHTML=`<div class="workspace explore-workspace"><div class="section-row"><h1 class="people-title">${config[1]}</h1><button type="button" class="action-icon" id="new-context" aria-label="${esc(config[1])} 연구 추가" title="${esc(config[1])} 연구 추가">${UI_PLUS}</button></div>${kind==='topics'?`<div class="topic-search"><button class="search-toggle" type="button" id="topic-search-toggle" aria-label="주제 검색 열기" aria-expanded="false"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"></circle><path d="m20 20-4-4"></path></svg></button><label id="topic-search-panel" hidden><span class="sr-only">주제 검색</span><input type="search" id="topic-search" placeholder="주제 검색"></label></div>`+suggestedTopics():''}${list.length?list.map(([k,ns])=>`<section class="explore-group"><h2><a href="${idHash('@'+config[4]+':'+k)}">${esc(k)}</a> <span class="count">${ns.length}</span></h2>${ns.map(n=>`<a class="explore-note" href="${idHash(n.person)}?note=${encodeURIComponent(n.id)}"><span><b>${esc(n.title)}</b><small>${esc(virtualPerson(n.person)?.display||n.person)} · ${n.author==='mine'?'민수':'보라'}</small></span><span>→</span></a>`).join('')}</section>`).join(''):'<div class="empty">기록 없음</div>'}</div><a class="back bottom-back" href="#/home">← 처음</a>`;const open=()=>{newContextKind=config[4];$('#context-title').textContent=config[5]+' 연구 시작';$('#context-label').textContent=config[5];$('#context-name').placeholder=config[6];$('#context-name').value='';$('#context-dialog').showModal()};$('#new-context').onclick=open;document.querySelector('#empty-context')?.addEventListener('click',open);$('#topic-search-toggle')?.addEventListener('click',e=>{const panel=$('#topic-search-panel'),open=panel.hidden;panel.hidden=!open;e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.setAttribute('aria-label',open?'주제 검색 닫기':'주제 검색 열기');if(open)$('#topic-search').focus();else{$('#topic-search').value='';$('#topic-search').dispatchEvent(new Event('input'))}});$('#topic-search')?.addEventListener('input',e=>{const q=e.target.value.trim().toLocaleLowerCase();document.querySelectorAll('.topic-suggestions section').forEach(section=>{let count=0;section.querySelectorAll('a').forEach(a=>{a.hidden=!!q&&!a.textContent.toLocaleLowerCase().includes(q);if(!a.hidden)count++});section.hidden=!count});document.querySelectorAll('.explore-group').forEach(group=>{group.hidden=!!q&&!group.textContent.toLocaleLowerCase().includes(q)})})}
$('#context-form').onsubmit=e=>{e.preventDefault();const name=$('#context-name').value.trim();if(!name)return;$('#context-dialog').close();location.hash=idHash('@'+newContextKind+':'+name)};
const routeScrolls=new Map();
function route(){const hash=location.hash||'#/home';const [path,qs]=hash.startsWith('#/')?hash.slice(2).split('?'):['home',''];const parts=path.split('/');const kind=parts[0]||'home';if(kind==='person'){let name;try{name=decodeURIComponent(parts.slice(1).join('/'))}catch{name=''}personNotesFilter='all';personView(name);const noteId=new URLSearchParams(qs||'').get('note');if(noteId)setTimeout(()=>{const el=document.getElementById('note-'+noteId);if(el){el.classList.add('note-highlight');el.scrollIntoView({block:'center',behavior:'smooth'});setTimeout(()=>el.classList.remove('note-highlight'),4000)}},100)}else if(kind==='people')peopleView();else if(kind==='family')familyView();else if(kind==='routine')routineView();else if(['books','topics','verses'].includes(kind))exploreView(kind);else homeView();requestAnimationFrame(()=>window.scrollTo(0,routeScrolls.get(hash)||0))}
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#/"]');if(a)routeScrolls.set(location.hash||'#/home',window.scrollY)});
window.addEventListener('scroll',()=>{routeScrolls.set(location.hash||'#/home',window.scrollY)},{passive:true});

function displayImage(src,noteId,description=''){const parent=document.querySelector('[data-images="'+noteId+'"]');if(!parent)return;const image=document.createElement('img');image.className='note-image';image.alt=description||'첨부 이미지';image.setAttribute('role','button');image.setAttribute('aria-label',(description||'첨부 이미지')+' 크게 보기');image.tabIndex=0;image.src=src;image.onclick=()=>{$('#full-image').src=src;$('#image-dialog').showModal()};image.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();image.click()}};parent.append(image)}
function fileUrl(path){return BASE+'/storage/v1/object/public/bible-study-photos/'+path.split('/').map(encodeURIComponent).join('/')}
async function loadImages(ns){if(!ns.length)return;const ids=ns.map(n=>n.id).filter(id=>/^[0-9a-f-]{36}$/i.test(id));if(!ids.length)return;try{const url='note_id=in.('+ids.join(',')+')';const [a,b]=await Promise.all([fetch(BASE+'/rest/v1/study_images?select=note_id,data_url'+(descriptionsAvailable?',alt_text':'')+'&'+url,{headers}),fetch(BASE+'/rest/v1/study_files?select=note_id,path'+(descriptionsAvailable?',alt_text':'')+'&'+url,{headers})]);if(!a.ok||!b.ok)throw Error();const legacy=await a.json(),files=await b.json();for(const img of legacy)if(/^data:image\/(jpeg|png|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(img.data_url))displayImage(img.data_url,img.note_id,img.alt_text);files.sort((x,y)=>x.path.split('/').pop().localeCompare(y.path.split('/').pop()));for(const f of files)if(/^[0-9a-f]{64}\/[0-9a-f-]{36}\.(jpg|png|webp|gif)$/.test(f.path))displayImage(fileUrl(f.path),f.note_id,f.alt_text)}catch{document.querySelectorAll('[data-images]').forEach(x=>x.textContent='이미지를 불러오지 못했습니다.')}}
async function rpc(name,payload){const r=await fetch(BASE+'/rest/v1/rpc/'+name,{method:'POST',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify(payload)});const value=await r.json().catch(()=>null);if(!r.ok){const error=Error(value?.message||'요청을 완료하지 못했습니다.');error.code=value?.code;throw error}return value}
async function issueUpload(password){const result=await rpc('study_issue_upload',{p_password:password});if(!result?.ok)throw Error(result?.error||'이미지 업로드를 시작하지 못했습니다.');return result.token}
async function uploadData(data,token,position=0){const blob=await (await fetch(data)).blob(),ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif'}[blob.type];if(!ext||blob.size>5242880)throw Error('지원하지 않는 이미지 형식이거나 5MB를 초과했습니다.');const path=token+'/'+position.toString(16)+crypto.randomUUID().slice(1)+'.'+ext;const r=await fetch(BASE+'/storage/v1/object/bible-study-photos/'+path,{method:'POST',headers:{...headers,'Content-Type':blob.type},body:blob});if(!r.ok)throw Error('이미지를 올리지 못했습니다. 잠시 후 다시 시도해 주세요.');return path}
async function cleanup(){try{const paths=await rpc('study_cleanup_candidates',{});if(!paths?.length)return;const r=await fetch(BASE+'/storage/v1/object/bible-study-photos',{method:'DELETE',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({prefixes:paths})});if(r.ok)await rpc('study_cleanup_done',{p_paths:paths})}catch{}}
async function abandon(token){if(token){try{await rpc('study_abandon_upload',{p_token:token});await cleanup()}catch{}}}

