document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{const d=b.closest('dialog');if(d.id==='edit-dialog')closeEditor();else d.close()});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){if(d.id==='edit-dialog')closeEditor();else d.close()}}));$('#edit-dialog').addEventListener('cancel',e=>{e.preventDefault();closeEditor()});window.addEventListener('beforeunload',e=>{if($('#edit-dialog').open&&(draftSnapshot()!==draftBaseline||imagesChanged)){saveDraft();e.preventDefault();e.returnValue=''}});
async function getLegacyImages(){let rows=[],offset=0;for(;;){const r=await fetch(BASE+'/rest/v1/study_images?select=id,note_id,data_url'+(descriptionsAvailable?',alt_text':'')+'&order=id.asc&limit=100&offset='+offset,{headers});if(!r.ok)throw Error('이미지를 불러오지 못했습니다.');const page=await r.json();rows.push(...page);if(page.length<100)return rows;offset+=page.length}}
async function getBackupImages(){const legacy=await getLegacyImages();const files=await getAll('study_files','id,note_id,path,'+(descriptionsAvailable?'alt_text,':'')+'created_at');files.sort((a,b)=>a.note_id.localeCompare(b.note_id)||a.path.split('/').pop().localeCompare(b.path.split('/').pop()));const stored=[];for(const f of files){const r=await fetch(fileUrl(f.path));if(!r.ok)throw Error('저장된 이미지를 불러오지 못했습니다.');stored.push({id:f.id,note_id:f.note_id,alt_text:f.alt_text||'',data_url:await fileData(await r.blob())})}return legacy.concat(stored)}
$('#move-images').onclick=async e=>{const button=e.currentTarget;button.disabled=true;let moved=0,token=null;try{const images=await getLegacyImages();if(!images.length){alert('옮길 기존 이미지가 없습니다.');return}if(!confirm(`기존 이미지 ${images.length}개를 파일 저장 공간으로 옮깁니다. 이미지가 확인된 뒤에만 기존 데이터가 삭제됩니다. 계속할까요?`))return;const password=prompt('작성 비밀번호를 입력해 주세요.');if(password===null)return;for(const noteId of [...new Set(images.map(x=>x.note_id))]){const same=images.filter(x=>x.note_id===noteId);token=await issueUpload(password);const mapping=[];for(const image of same)mapping.push({id:image.id,path:await uploadData(image.data_url,token,mapping.length)});const result=await rpc('study_migrate_images',{p_password:password,p_note:noteId,p_upload_token:token,p_mapping:mapping});if(!result?.ok)throw Error(result?.error||'이미지를 옮기지 못했습니다.');token=null;moved+=same.length;button.textContent=`이미지 옮기는 중 (${moved}/${images.length})`}await load();route();alert(`이미지 ${moved}개를 옮겼습니다.`)}catch(err){await abandon(token);alert(`${moved}개를 옮긴 뒤 중단됐습니다. 남은 이미지는 원래 위치에 유지됩니다. ${err.message}`)}finally{button.disabled=false;button.textContent='기존 이미지 옮기기'}};
$('#backup').onclick=async e=>{const password=prompt('전체 백업을 위해 비밀번호를 입력해 주세요.');if(password===null)return;const button=e.currentTarget;button.disabled=true;button.textContent='백업 준비 중…';try{let extra;try{extra=await rpc('study_extra_backup',{p_password:password})}catch(err){if(err.code!=='PGRST202')throw err;if(!confirm('전체 백업 설정이 아직 완료되지 않았습니다. 지금은 연구 기록과 이미지만 백업할까요? 성구와 영적 일과는 포함되지 않습니다.'))return}if(extra&&!extra.ok)throw Error(extra.error||'성구와 일과를 불러오지 못했습니다.');await load();const images=await getBackupImages();const backup={format:'bible-study-backup',version:extra?2:1,exported_at:new Date().toISOString(),people,notes,images,...(extra?{extra}:{})};const blob=new Blob([JSON.stringify(backup)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='성경연구-백업-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000)}catch(err){alert('백업을 만들지 못했습니다: '+err.message)}finally{button.disabled=false;button.textContent='백업 내려받기'}};
$('#restore').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const backup=JSON.parse(await f.text());if(backup.format!=='bible-study-backup'||![1,2].includes(backup.version)||!Array.isArray(backup.notes)||!Array.isArray(backup.images)||!Array.isArray(backup.people))throw Error('지원하지 않는 백업 파일입니다.');if(!confirm('백업의 자료를 현재 자료에 추가합니다. 이미 있는 항목은 유지합니다. 계속할까요?'))return;const password=prompt('작성 비밀번호를 입력해 주세요.');if(password===null)return;if(backup.version===2){if(Array.isArray(backup.extra?.connections)&&!connectionsReady)throw Error('연구 연결 자료를 가져오려면 저장 공간 설정이 필요합니다.');if(!backup.extra||!['verses','preferences','settings','checks'].every(k=>Array.isArray(backup.extra[k])))throw Error('성구와 일과 백업을 확인해 주세요.');const ready=await rpc('study_extra_backup',{p_password:password});if(!ready?.ok)throw Error(ready?.error||'백업 연결을 확인해 주세요.')}await load();let restored=0,skipped=0;for(const person of backup.people){if(allPeople().some(p=>p.name===person.name))continue;await change('person',{name:person.name,era:person.era,search_term:person.search_term||''},password);people.push(person)}for(const n of backup.notes){if(notes.some(x=>x.person===n.person&&x.author===n.author&&x.title===n.title&&x.body===n.body)){skipped++;continue}const backupImages=backup.images.filter(i=>i.note_id===n.id),images=backupImages.map(i=>i.data_url);let token=null;try{const filePaths=[];if(images.length){token=await issueUpload(password);for(const image of images)filePaths.push(await uploadData(image,token,filePaths.length))}await change('restore',{person:n.person,author:n.author,title:n.title,body:n.body,created_at:n.created_at,verse:n.verse||'',book:n.book||'',topic:n.topic||'',reference_url:n.reference_url||'',images:[],image_descriptions:backupImages.map(i=>i.alt_text||''),file_paths:filePaths,upload_token:token},password);token=null}catch(err){await abandon(token);throw err}notes.push(n);restored++}if(backup.version===2){const result=await rpc('study_extra_restore',{p_password:password,p_data:backup.extra});if(!result?.ok)throw Error(result?.error||'성구와 일과를 가져오지 못했습니다.');await loadHomeVerses();routineData=null}await load();route();alert(`가져오기 완료: 연구 기록 ${restored}개 추가, ${skipped}개 건너뜀.`)}catch(err){alert('가져오기를 완료하지 못했습니다. 일부 항목은 이미 추가됐을 수 있습니다. '+err.message);try{await load();route()}catch{}}finally{e.target.value=''}};
let connections=[],connectionsReady=false;
async function loadConnections(){try{connections=await getAll('study_connections');connectionsReady=true}catch{connections=[];connectionsReady=false}}
function connectionSection(kind,source,title){
 if(!connectionsReady)return '';
 const list=connections.filter(c=>c.kind===kind&&(c.source===source));
 if(!list.length)return `<div class="connection-empty"><span>${esc(title)}</span><button type="button" class="action-icon" data-connection-add="${kind}" aria-label="${esc(title)} 추가" title="${esc(title)} 추가">${UI_PLUS}</button></div>`;
 return `<section class="connections-section"><div class="connection-heading"><h2>${esc(title)}</h2><button type="button" class="action-icon" data-connection-add="${kind}" aria-label="${esc(title)} 추가" title="${esc(title)} 추가">${UI_PLUS}</button></div>${list.map(c=>{let target=kind==='person'?(c.source===source?c.target:c.source):c.target;let link=kind==='resource'?`<a href="${esc(safeUrl(target)||'#')}" target="_blank" rel="noopener noreferrer">${esc(c.title)} ↗</a>`:kind==='person'?`<a href="${idHash(target)}">${esc(target)} →</a>`:`<strong>${esc(c.title)}</strong>${target?`<a class="connection-topic" href="${idHash('@topic:'+target)}"># ${esc(target)}</a>`:''}`;return `<div class="connection-item">${link}${c.description?`<p>${esc(c.description)}</p>`:''}<div class="connection-actions"><button class="link" data-connection-edit="${esc(c.id)}">수정</button><button class="link" data-connection-delete="${esc(c.id)}">삭제</button></div></div>`}).join('')}</section>`
}
function openConnection(kind,source,id){
 const c=connections.find(x=>x.id===id),isResource=kind==='resource',isPerson=kind==='person';
 $('#connection-form').reset();$('#connection-id').value=id||'';$('#connection-kind').value=kind;$('#connection-source').value=c?.source||source;
 $('#connection-title').textContent=isResource?'JW.ORG 자료':isPerson?'관련 인물':'다음 질문';
 $('#connection-label').textContent=isResource?'자료 제목':isPerson?'이름':'질문';
 $('#connection-name').value=c?.title||'';$('#connection-target').value=c?.target||'';$('#connection-description').value=c?.description||'';
 $('#connection-target-label').hidden=isPerson;$('#connection-description-label').hidden=isPerson;
 $('#connection-target-text').textContent=isResource?'자료 주소':'관련 주제 (선택 사항)';$('#connection-target').required=isResource;
 $('#connection-name').setAttribute('list',isPerson?'connection-people':'');$('#connection-people').innerHTML=isPerson?allPeople().filter(x=>x.name!==source).map(x=>`<option value="${esc(x.name)}"></option>`).join(''):'';
 $('#connection-message').textContent='';$('#connection-dialog').showModal();
}
function bindConnections(source){
 document.querySelectorAll('[data-connection-add]').forEach(b=>b.onclick=()=>openConnection(b.dataset.connectionAdd,source));
 document.querySelectorAll('[data-connection-edit]').forEach(b=>b.onclick=()=>{const c=connections.find(x=>x.id===b.dataset.connectionEdit);if(c)openConnection(c.kind,source,c.id)});
 document.querySelectorAll('[data-connection-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('이 항목을 지울까요?'))return;const password=prompt('작성 비밀번호를 입력해 주세요.');if(password===null)return;try{const r=await rpc('study_connection_change',{p_password:password,p_action:'delete',p_data:{id:b.dataset.connectionDelete}});if(!r?.ok)throw Error(r?.error||'지우지 못했습니다.');await loadConnections();personView(source)}catch(e){alert(e.message)}});
}
$('#connection-form').onsubmit=async e=>{
 e.preventDefault();const btn=e.target.querySelector('button[type=submit]'),kind=$('#connection-kind').value,source=$('#connection-source').value,id=$('#connection-id').value,name=$('#connection-name').value.trim();let target=$('#connection-target').value.trim();
 if(kind==='person'){target=name;if(!allPeople().some(p=>p.name===name)||name===source){$('#connection-message').textContent='목록에서 다른 인물을 선택해 주세요.';return}}
 if(kind==='resource'){try{const u=new URL(target);if(u.protocol!=='https:'||!(u.hostname==='jw.org'||u.hostname.endsWith('.jw.org')))throw Error();}catch{$('#connection-message').textContent='JW.ORG 자료 주소를 입력해 주세요.';return}}
 btn.disabled=true;try{const r=await rpc('study_connection_change',{p_password:$('#connection-password').value,p_action:id?'update':'create',p_data:{id,kind,source,title:name,target,description:$('#connection-description').value.trim()}});if(!r?.ok)throw Error(r?.error||'저장하지 못했습니다.');await loadConnections();$('#connection-dialog').close();personView(currentPerson)}catch(err){$('#connection-message').textContent=err.message}finally{btn.disabled=false}
};

function topicQuestions(topic){const found=connections.filter(c=>c.kind==='question'&&c.target===topic);return found.length?`<section class="connections-section"><h2>가족 숭배 질문</h2>${found.map(c=>`<a class="topic-question" href="${idHash(c.source)}">${esc(c.title)} <span>→</span></a>`).join('')}</section>`:''}
$('#home-verse-form').onsubmit=setHomeVerse;$('#home-verse-mode').onchange=e=>changeVerse('mode',{mode:e.target.value});$('#home-verse-cancel').onclick=()=>{$('#home-verse-id').value='';$('#home-verse-reference').value='';$('#home-verse-text').value='';$('#home-verse-save').textContent='+ 성구 저장';$('#home-verse-cancel').hidden=true};$('#routine-setting-form').onsubmit=saveRoutineSetting;window.addEventListener('hashchange',route);async function start(){let timer;try{await Promise.race([Promise.all([load(),loadHomeVerses()]),new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('시간 초과')),12000)})]);route();cleanup()}catch(e){appMessage('기록을 불러오지 못했습니다. 연결 상태를 확인해 주세요.')}finally{clearTimeout(timer)}}start();
